// FarmTile.cpp
void FarmTile::tick(Level *level, int x, int y, int z, Random *random)
{
    if (isNearWater(level, x, y, z) || level->isRainingAt(x, y + 1, z))
	{
        level->setData(x, y, z, 7);
    } else
	{
        int moisture = level->getData(x, y, z);
        if (moisture > 0)
		{
            level->setData(x, y, z, moisture - 1);
        } else
		{
            if (!isUnderCrops(level, x, y, z))
			{
                level->setTile(x, y, z, Tile::dirt_Id);
            }
        }
    }
}

// FarmTile.cpp
bool FarmTile::isUnderCrops(Level *level, int x, int y, int z)
{
    int r = 0;
    for (int xx = x - r; xx <= x + r; xx++)
        for (int zz = z - r; zz <= z + r; zz++)
		{
            int tile = level->getTile(xx, y + 1, zz);
            if (tile == Tile::crops_Id || tile == Tile::melonStem_Id || tile == Tile::pumpkinStem_Id || tile == Tile::potatoes_Id || tile == Tile::carrots_Id)
			{
                return true;
            }
        }
    return false;
}

// FarmTile.cpp
bool FarmTile::isNearWater(Level *level, int x, int y, int z)
{
    for (int xx = x - 4; xx <= x + 4; xx++)
        for (int yy = y; yy <= y + 1; yy++)
            for (int zz = z - 4; zz <= z + 4; zz++)
			{
                if (level->getMaterial(xx, yy, zz) == Material::water)
				{
                    return true;
                }
            }
    return false;
}

// ReedTile.cpp
void ReedTile::tick(Level *level, int x, int y, int z, Random* random)
{
	if (level->isEmptyTile(x, y + 1, z))
	{
		int height = 1;
		while (level->getTile(x, y - height, z) == id)
		{
			height++;
		}
		if (height < 3)
		{
			int age = level->getData(x, y, z);
			if (age == 15) 
			{
				level->setTile(x, y + 1, z, id);
				level->setData(x, y, z, 0);
			} 
			else 
			{
				level->setData(x, y, z, age + 1);
			}
		}
	}
}

// ReedTile.cpp
bool ReedTile::mayPlace(Level *level, int x, int y, int z) 
{
	int below = level->getTile(x, y - 1, z);
	if (below == id) return true;
	if (below != Tile::grass_Id && below != Tile::dirt_Id && below != Tile::sand_Id) return false;
	if (level->getMaterial(x - 1, y - 1, z) == Material::water) return true;
	if (level->getMaterial(x + 1, y - 1, z) == Material::water) return true;
	if (level->getMaterial(x, y - 1, z - 1) == Material::water) return true;
	if (level->getMaterial(x, y - 1, z + 1) == Material::water) return true;
	//printf("no water\n");
	return false;
}

// ReedTile.cpp
bool ReedTile::canSurvive(Level *level, int x, int y, int z)
{
	return mayPlace(level, x, y, z);
}

