bool TorchTile::checkCanSurvive(Level *level, int x, int y, int z)
{
	if (!mayPlace(level, x, y, z))
	{
		if (level->getTile(x, y, z) == id)
		{
			this->spawnResources(level, x, y, z, level->getData(x, y, z), 0);
			level->setTile(x, y, z, 0);
		}
		return false;
	}
	return true;
}

