{
	if (!level->isClientSide)
	{
		if (isLit && !level->hasNeighborSignal(x, y, z))
		{
			level->addToTickNextTick(x, y, z, id, 4);
		}
		else if (!isLit && level->hasNeighborSignal(x, y, z))
		{
			level->setTile(x, y, z, Tile::redstoneLight_lit_Id);
		}
	}
}

// RedlightTile.cpp
